import pandas as pd,numpy as np
from scipy.optimize import least_squares
c=pd.read_csv('/task/work/final_counts_edge.tsv',sep='\t').set_index('well')
m=pd.read_csv('/task/work/marker_final_v2.tsv',sep='\t').set_index('well')
x=c.join(m[['marker_per_cell']]).copy()
qc_fail={'D04','F08','B05','B07','F09'}
x['usable']=(~x.index.isin(qc_fail))&x.marker_per_cell.notna()
rows=list('ABCDEFGH'); cols=list(range(1,13))
def design(df):
 z=[np.ones(len(df))]
 for r in rows[1:]: z.append((np.asarray(df.index.str[0])==r).astype(float))
 for q in cols[1:]: z.append((np.asarray(df.index.str[1:].astype(int))==q).astype(float))
 return np.column_stack(z)
def ridge(X,y,lam):
 A=X.T@X+lam*np.diag([0]+[1]*(X.shape[1]-1))
 return np.linalg.solve(A,X.T@y)
def baseline(y,kind):
 ctr=x[x.usable&(x.role=='vehicle')]
 if kind=='global_median': return pd.Series(ctr[y].median(),index=x.index)
 if kind=='global_mean': return pd.Series(ctr[y].mean(),index=x.index)
 if kind=='row_median': return pd.Series(x.index.str[0].map(ctr.groupby(ctr.index.str[0])[y].median()).to_numpy(),index=x.index)
 if kind=='col_median': return pd.Series(x.index.str[1:].astype(int).map(ctr.groupby(ctr.index.str[1:].astype(int))[y].median()).to_numpy(),index=x.index)
 lam=float(kind.split('_')[1])
 d=ctr.copy(); X=design(d); yv=np.log(d[y].to_numpy(float))
 b=ridge(X,yv,lam)
 return pd.Series(np.exp(design(x)@b),index=x.index)
def model_logc(logc,h,ec,bottom): return bottom+(1-bottom)/(1+np.exp(h*(logc-np.log(ec))))
def fit_curve(dos,resp):
 dos=np.asarray(dos,float); resp=np.asarray(resp,float)
 # physically constrained parameters: log_ec, log_h, logit_bottom
 def resid(p):
  ec=np.exp(p[0]); h=np.exp(p[1]); bottom=1/(1+np.exp(-p[2]))
  return model_logc(np.log(dos),h,ec,bottom)-resp
 best=None
 for ec0 in [.03,.1,.3,1,3,10,30]:
  for h0 in [.5,1,2,5]:
   for b0 in [.0001,.01,.1,.3]:
    p0=[np.log(ec0),np.log(h0),np.log(b0/(1-b0))]
    try:
     r=least_squares(resid,p0,bounds=([-20,-5,-12],[5,5,12]),max_nfev=5000)
     ss=np.sum(r.fun**2)
     if best is None or ss<best[0]: best=(ss,r.x)
    except Exception: pass
 if best is None: return None
 p=best[1]; ec=np.exp(p[0]); h=np.exp(p[1]); bottom=1/(1+np.exp(-p[2]))
 # reported potency is c where response=.5; only if bottom<.5
 if bottom<.5 and ec<=dos.max(): pot=ec
 else:
  # numerical descending crossing if any
  grid=np.logspace(np.log10(dos.min()),np.log10(dos.max()),2000)
  vals=model_logc(np.log(grid),h,ec,bottom)
  idx=np.where(vals<=.5)[0]
  pot=grid[idx[0]] if len(idx) else np.nan
 return dict(ec=ec,h=h,bottom=bottom,pot=pot,rms=np.sqrt(best[0]/len(dos)),values=model_logc(np.log(dos),h,ec,bottom))
for y in ['n_cells','marker_per_cell']:
 print('\n########',y)
 for kind in ['global_median','global_mean','row_median','col_median','ridge_0.01','ridge_0.1','ridge_1','ridge_10','ridge_100']:
  pred=baseline(y,kind); x['pred']=pred; x['resp']=x[y]/x.pred
  print('\n--',kind)
  for cp,g in x[(x.role=='compound')&x.usable].groupby('compound'):
   fit=fit_curve(g.dose_uM,g.resp)
   if fit is None: print(cp,'FIT FAIL'); continue
   print(f'{cp:9s} pot={fit["pot"]:.5g} ec={fit["ec"]:.4g} h={fit["h"]:.2f} bot={fit["bottom"]:.3f} rms={fit["rms"]:.3f} obs='+','.join(f'{r:.2f}' for r in g.sort_values('dose_uM').resp)+')')
